		private static FeeDetails ReadPaidFeeDetails(SqlDataReader oSqlDataReader)
		{
			FeeDetails oFeeDetails = null;
			while (oSqlDataReader.Read())
			{
				oFeeDetails = new FeeDetails();
				oFeeDetails.Student_Id = Convert.ToInt32(oSqlDataReader["Student_Id"]);
				oFeeDetails.FeeMode = Convert.ToString(oSqlDataReader["FeeMode"]);
				oFeeDetails.Paid_Date = Convert.ToDateTime(oSqlDataReader["PaidDate"]);
				oFeeDetails.Receipt_Number = Convert.ToString(oSqlDataReader["ReceiptNo"]);
				oFeeDetails.Remarks = Convert.ToString(oSqlDataReader["Remarks"]);
				oFeeDetails.AmtPaid = Convert.ToInt32(oSqlDataReader["ActualAmt"]);
				oFeeDetails.TotalAmtToPay = Convert.ToInt32(oSqlDataReader["MaxAmtForTheTransaction"]);
				oFeeDetails.PaymentMode = Convert.ToString(oSqlDataReader["PaymentMode"]);
				oFeeDetails.Bank_Id = Convert.ToInt32(oSqlDataReader["Bank_Id"]);
				oFeeDetails.Cheque_Amount = Convert.ToInt32(oSqlDataReader["Cheque_Amount"]);
				oFeeDetails.Cheque_Number = Convert.ToString(oSqlDataReader["Cheque_Number"]);
				oFeeDetails.LateFee = Convert.ToInt32(oSqlDataReader["LateFee"]);
				oFeeDetails.Cheque_Date = Convert.ToDateTime(oSqlDataReader["Cheque_Date"]);
				oFeeDetails.LateFeeRemark = Convert.ToString(oSqlDataReader["LateFeeRemark"]);
				oFeeDetails.ConcessionAmt = Convert.ToInt32(oSqlDataReader["ConcessionAmt"]);
				oFeeDetails.DepositBankId = Convert.ToInt32(oSqlDataReader["DepositBankId"]);
				oFeeDetails.IsDirectlyDeposited = Convert.ToBoolean(oSqlDataReader["IsDirectlyDeposited"]);
				oFeeDetails.ChallanNo = oSqlDataReader["ChallanNo"] == DBNull.Value ? String.Empty : oSqlDataReader["ChallanNo"].ToString();
			}
			return oFeeDetails;
		}

